import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from vlib import *

D2 = ("CAT", "XAT")

# 001 ------------------------------------------------------------------ nostalgia
sp("V04-F-001", "Psychology", "Nostalgia, once treated as a disorder, is now seen by many psychologists as a mood that usually helps rather than harms.", "Easy",
   ["Nostalgia was once treated by physicians as a disorder, a homesickness thought to be severe enough to weaken soldiers and sailors serving far from home.",
    "Many psychologists now take a different view, describing nostalgia as a mood that does useful work rather than one that simply drags people backwards.",
    "When people feel lonely or unsure of themselves, recalling warm episodes from earlier life tends to restore their sense of being connected to others.",
    "Such memories also seem to lend a feeling of continuity, a reassurance that the person who lived those moments is the same person now facing the present.",
    "None of this means that longing for the past is always healthy, since a mind that lives only in memory may neglect the life in front of it.",
    "The point is rather that nostalgia, indulged in moderation, is more often a resource than a symptom."],
   "This medical label lingered for a long time, and even after doctors abandoned it the word kept a faint suggestion of weakness and self-indulgence.",
   [1, 3, 4, 6],
   "The missing sentence speaks of 'This medical label', which can only point back to the first sentence, where physicians treat nostalgia as a disorder. It also sets up the next sentence: the lingering suggestion of weakness is what 'Many psychologists now take a different view' turns against. Only gap (1) lies between these two sentences.",
   {3: "At gap (2) the paragraph is already listing the benefits of nostalgia; a sentence about the old medical label would break into that list and has no nearby referent for 'This medical label'.",
    4: "At gap (3) the paragraph has moved from loneliness to continuity and is about to qualify its claim; returning to the history of the diagnosis here interrupts the argument.",
    6: "At gap (4) the paragraph has reached its conclusion that nostalgia is 'more often a resource than a symptom'; going back to the old label after that verdict is out of sequence."},
   "Placing the sentence near the end because it mentions weakness, which seems to echo the warning that longing for the past is not always healthy.",
   "V04F-nostalgia-function", "A clear backward reference to the opening sentence fixes the position within a sentence or two.",
   cognitive="Understanding")

# 002 ------------------------------------------------------------------ habits and context
sp("V04-F-002", "Psychology", "Habits draw much of their strength from the cues in their settings, so changes of setting are chances to break or rebuild them.", "Medium",
   ["Habits are often described as private achievements of willpower, but much of their strength is borrowed from the settings in which they form.",
    "A behaviour repeated in the same place, at the same hour and after the same preceding action gradually comes to be triggered by those cues rather than by a decision.",
    "The same dependence on context explains why habits often loosen when people move house, change jobs or go away on a long journey.",
    "With the old cues gone, behaviour that once ran automatically has to be chosen again, and for a short period it becomes open to revision.",
    "Those who want to drop a habit can therefore treat such transitions as opportunities, while those who want to keep one should expect to rebuild it deliberately."],
   "Someone who always lights a cigarette with the first cup of morning tea may find that the craving arrives with the tea itself, before any thought of smoking has formed.",
   [0, 2, 4, 5],
   "The missing sentence is an illustration: the craving that 'arrives with the tea itself, before any thought of smoking' is a case of behaviour 'triggered by those cues rather than by a decision'. It must therefore come straight after that claim, and it must come before 'The same dependence on context', which widens the point from a single cue to whole settings. That is gap (2).",
   {0: "Gap (1) is before the opening sentence; an example cannot open the paragraph before the claim it illustrates, and the first sentence is the natural introduction of the subject.",
    4: "At gap (3) the paragraph is discussing how moving house or changing jobs removes cues; a single example of a cue firing a craving belongs to the earlier claim, and 'therefore' in the next sentence must follow the point about behaviour becoming 'open to revision'.",
    5: "At gap (4) the paragraph has ended with practical advice; returning to a basic illustration of how a cue triggers behaviour after the conclusion is out of place."},
   "Choosing gap (3) on the thought that the tea example shows why a change of setting matters, although the example shows only a cue at work, not a change of setting.",
   "V04F-habit-cues-context", "The example could loosely sit near any sentence about cues; the solver must match it to the specific claim it illustrates.")

# 003 ------------------------------------------------------------------ procrastination
sp("V04-F-003", "Psychology", "Deliberate delay can protect a person's self-image by supplying an excuse for failure, but at the cost of making success meaningless.", "Difficult",
   ["Procrastination is usually explained as a failure of time management, as though the delayer had simply misjudged how long a task would take.",
    "That explanation fits some cases, but it struggles with the person who knows exactly how long the work will take and still postpones it until the last night.",
    "For such a person, delay may serve a purpose that has little to do with the clock.",
    "If the work is done hastily and turns out badly, the poor result can be blamed on the lack of time rather than on any lack of ability.",
    "Delay, in other words, buys an excuse in advance, and the excuse protects a self-image that an honest, unhurried attempt might threaten.",
    "A good mark earned in a frantic night proves little about what the delayer could really do, and so the self-image is shielded but never actually confirmed.",
    "This is why advice about calendars and planners so often fails such people: it treats a problem of self-protection as if it were a problem of arithmetic."],
   "Yet the protection is bought at a price, because the same excuse that softens a failure also empties a success of its meaning.",
   [2, 3, 5, 7],
   "The missing sentence needs 'the protection' to have been described, which happens only when the excuse is said to protect a self-image. It also announces a price, 'empties a success of its meaning', which the next sentence spells out with the good mark that 'proves little'. So it sits between the sentence about buying an excuse and the sentence about the good mark: gap (3).",
   {2: "At gap (1) only the time-management view and its weakness have been stated; no protection has been mentioned, so 'the protection' and 'the same excuse' have nothing to refer to.",
    3: "At gap (2) the paragraph has only said that delay may serve some purpose; the excuse and the self-image it protects come in the following two sentences, so the sentence would comment on a mechanism not yet described.",
    7: "At gap (4) the price has already been shown by the good mark that 'proves little', and the paragraph has drawn its conclusion about planners; stating the price after both would repeat a point the reader has already been given."},
   "Choosing gap (4) because the sentence sounds like a general verdict, without noticing that the sentence about the frantic night is the illustration of exactly this price and must follow it.",
   "V04F-procrastination-self-image",
   "The decisive clue is a link of content, not a pronoun: the 'good mark' sentence silently presupposes the claim about success losing its meaning, and the closing gap is tempting.",
   exams=D2)

# 004 ------------------------------------------------------------------ anchoring
sp("V04-F-004", "Psychology", "Opening first in a negotiation helps only those who already know what the thing is worth.", "Medium",
   ["In many negotiations the first number spoken aloud exerts a pull on everything that follows.",
    "Even when both sides know the opening figure is a tactic, later offers tend to cluster around it, moving away from it less than the facts would justify.",
    "This has led some advisers to recommend that negotiators should always move first and open boldly.",
    "The advice is not wrong, but it rests on an assumption that is easy to overlook: that the person who opens knows roughly what the thing is worth.",
    "A seller who badly underestimates the value of an old painting and names a modest price anchors the whole bargaining in the buyer's favour.",
    "The buyer, who has done some research, has every reason to accept at once and say nothing."],
   "Opening first, then, is a strength only for the well informed; for anyone else it can be a costly way of revealing ignorance to a rival with no reason to correct it.",
   [2, 3, 5, 6],
   "The missing sentence is the conclusion ('then') of the paragraph's qualification. It depends on the assumption, introduced in the fourth sentence, that the opener 'knows roughly what the thing is worth', and on the painting example, which shows what happens when that assumption fails. Its 'rival with no reason to correct it' is the buyer of the last sentence, who will 'accept at once and say nothing', so it comes after the example is complete, at gap (4).",
   {2: "At gap (1) the paragraph has only described the pull of the first number; the advice to move first and the condition of being well informed have not yet been raised, so 'then' has nothing to conclude from.",
    3: "At gap (2) the advice to open first has been reported but not yet qualified; the idea that opening is 'a strength only for the well informed' comes from the next sentence and cannot be concluded before it.",
    5: "At gap (3) the sentence would split the painting example in two: 'The buyer' in the following sentence continues the seller's story and must stay next to it, so the conclusion cannot come between them; besides, the 'rival with no reason to correct it' has not yet been shown keeping silent."},
   "Choosing gap (3) because the painting example seems complete once the seller has named a modest price, overlooking that the buyer's silent acceptance is part of the same illustration.",
   "V04F-anchoring-first-offers", "The conclusion could seem to fit after the example's first half; the solver must see that the example runs over two sentences.")

# 005 ------------------------------------------------------------------ gifts
sp("V04-F-005", "Society and culture", "Gifts create unspoken obligations to repay, which is why sensible givers avoid presents that cannot be matched.", "Easy",
   ["A gift looks like the simplest of transactions: one person gives, another receives, and nothing more is owed.",
    "In practice, gifts in most societies create obligations that are understood without ever being spoken aloud.",
    "Such expectations explain why an extravagant present, even one offered with the best of intentions, can cause embarrassment rather than delight.",
    "A recipient who cannot hope to match it is placed in a debt that may never be repaid, and the generosity begins to feel like a quiet assertion of superiority.",
    "For this reason, careful givers often choose presents whose value can comfortably be returned.",
    "Far from being a lapse in generosity, such restraint is a way of keeping the relationship one between equals."],
   "The recipient is expected to accept graciously, to remember the gesture and, sooner or later, to give something of comparable value in return.",
   [1, 2, 4, 6],
   "The missing sentence lists the unspoken obligations that the second sentence announces, and it supplies the 'expectations' that the third sentence refers to as 'Such expectations'. It must therefore follow 'obligations that are understood without ever being spoken aloud' and precede the sentence about extravagant presents: gap (2).",
   {1: "At gap (1) the paragraph has just said that 'nothing more is owed'; listing the recipient's duties before 'In practice' turns the argument would contradict that sentence without the contrast that introduces the obligations.",
    4: "At gap (3) the paragraph is explaining the embarrassment of an unmatched present, and 'For this reason' must follow the sentence about the debt that may never be repaid; a general list of duties would break that link.",
    6: "At gap (4) the paragraph has concluded that restraint keeps the relationship between equals; a basic statement of what recipients owe comes far too late."},
   "Choosing gap (1) because the sentence seems to correct the naive view directly, missing that 'In practice' is the sentence that makes that correction.",
   "V04F-gift-reciprocity", "The missing sentence fills an obvious slot between a general claim and a sentence that begins 'Such expectations'.",
   cognitive="Understanding")

# 006 ------------------------------------------------------------------ accents
sp("V04-F-006", "Society and culture", "The prestige of an accent comes from the status of its speakers rather than from its sounds, and the bias persists because it goes unnoticed.", "Difficult",
   ["Ask people why one accent sounds educated and another sounds careless, and they will usually point to the sounds themselves: clarity, crispness, a certain precision.",
    "If refinement really lived in the sound, it would not change its value at a border.",
    "What listeners hear as clarity is better understood as familiarity with the speech of people who already hold status, so that an accent gains prestige by association, much as an address or a school does.",
    "None of this makes such judgements harmless.",
    "Because they feel like perceptions rather than prejudices, they are seldom examined, and a speaker can be passed over without anyone believing that the accent played any part.",
    "The real difficulty is not that people defend accent hierarchies openly but that they rarely notice holding them at all."],
   "Linguists tend to distrust such answers, noting that a vowel heard as refined in one country may be heard as rustic in another.",
   [1, 2, 3, 5],
   "The missing sentence responds to 'such answers', the explanations people give in the first sentence, and it supplies the comparison between countries that the next sentence presupposes: 'it would not change its value at a border' only makes sense once a vowel has been shown to change value between countries. Hence gap (1).",
   {2: "At gap (2) the sentence about the border would already have appeared with no comparison between countries before it, and 'such answers' would be separated from the answers it refers to.",
    3: "At gap (3) the paragraph has already given its own explanation, prestige by association; saying that linguists distrust 'such answers' here would seem to reject that explanation rather than the popular one.",
    5: "At gap (4) the paragraph is discussing the unnoticed harm of accent judgements; evidence against the popular explanation belongs at the start of the argument, not after its consequences."},
   "Choosing gap (2) on the view that the sentence about the border is a rhetorical retort that can follow the first sentence directly, when in fact it depends on a cross-country example.",
   "V04F-accent-prestige",
   "The lock is a silent presupposition (the 'border' sentence needs a comparison between countries), and gap (3) is tempting because the missing sentence looks like supporting evidence for the association view.",
   exams=D2)

# 007 ------------------------------------------------------------------ gossip
sp("V04-F-007", "Society and culture", "Gossip enforces a community's norms without courts, but it enforces bad norms as readily as good ones.", "Medium",
   ["Gossip has a poor reputation, and most moral traditions warn against speaking about people behind their backs.",
    "Some anthropologists, however, have argued that in small communities gossip performs a service that no formal institution could easily replace.",
    "Where there are no courts or police close at hand, the knowledge that one's conduct will be discussed is a powerful reason to behave well.",
    "A trader who cheats a customer, or a neighbour who shirks the shared work of the harvest, soon finds the story travelling ahead of him.",
    "A young woman who refuses a match her family has chosen, or a son who abandons the family trade, may be discussed as harshly as any thief.",
    "Gossip, in short, enforces whatever norms a community happens to hold, good or bad, and its value depends on the norms it serves."],
   "Yet the same mechanism that disciplines the cheat can also punish the merely unconventional, since gossip does not distinguish between harm and difference.",
   [2, 3, 4, 6],
   "The missing sentence turns ('Yet') from the useful side of gossip to its darker side. It needs 'the cheat' to have appeared, which happens in the sentence about the trader, and it introduces 'the merely unconventional', who are illustrated by the young woman and the son in the next sentence. It therefore belongs at gap (3).",
   {2: "At gap (1) gossip's disciplinary role has only been announced, not described; 'the same mechanism' and 'the cheat' have nothing to refer to yet.",
    3: "At gap (2) no cheat has been mentioned, and the trader example must follow directly the claim about behaving well that it illustrates.",
    6: "At gap (4) the paragraph has already summed up 'in short'; the turn to the unconventional must come before the example of the young woman and the son, which would otherwise appear without explanation."},
   "Choosing gap (4) because the sentence sounds like a summary, overlooking that the two examples of the unconventional need it as their introduction.",
   "V04F-gossip-social-control", "A contrast marker plus a backward reference; the summary-like tone of the sentence makes the final gap tempting.")

# 008 ------------------------------------------------------------------ dress codes
sp("V04-F-008", "Society and culture", "Dress codes that are identical on paper can impose very unequal burdens, so their fairness should be judged by what they cost different people.", "Medium",
   ["Workplace dress codes are often defended as neutral rules that ask the same of everyone.",
    "The rules may be identical on paper, but their burden is not evenly spread.",
    "A standard of 'professional' appearance usually reflects the habits of whichever group first dominated a profession, and those who share those habits comply without noticing that any rule exists.",
    "Others must spend money, time and sometimes a part of their identity to meet the same standard.",
    "This does not mean that organisations should abandon standards of appearance altogether.",
    "It means that a rule's fairness should be judged by what it costs different people to follow, not merely by whether its wording is the same for all."],
   "An employee told that the way she naturally wears her hair looks untidy, for instance, is being asked to surrender something more personal than money.",
   [1, 2, 3, 4],
   "The missing sentence is an example ('for instance') of paying with 'a part of their identity', and its phrase 'more personal than money' only makes sense once money has been named as one of the costs. Both links point to the sentence beginning 'Others must spend money, time and sometimes a part of their identity', so the sentence goes after it, at gap (4).",
   {1: "At gap (1) the paragraph has only stated the defence of dress codes as neutral; no burden or cost has been mentioned, so the example has nothing to illustrate.",
    2: "At gap (2) the uneven burden has been asserted, but money has not yet been named, so 'more personal than money' has no point of comparison.",
    3: "At gap (3) the paragraph is describing those who comply without effort; an example of someone paying a personal cost would contradict that sentence before the contrasting 'Others' sentence has been reached."},
   "Choosing gap (2) because the example seems to illustrate the 'burden' in general, without noticing that it compares its cost with money, which is named only later.",
   "V04F-office-dress-codes", "Two gaps both follow claims about unequal burden; the phrase 'more personal than money' decides between them.")

# 009 ------------------------------------------------------------------ canals
sp("V04-F-009", "History and politics", "British canals rose and declined within a lifetime once railways arrived, showing how quickly infrastructure can become a relic.", "Easy",
   ["In the late eighteenth century, canals were the most advanced way of moving heavy goods across inland Britain.",
    "On still water a towpath horse could haul a barge whose cargo was many times what the same animal could manage with a wagon over unpaved, rutted tracks.",
    "Investors poured money into new waterways, and towns that lay on a canal prospered while those that did not fell behind.",
    "Within a few decades, however, the railways arrived, offering a speed that no barge could match.",
    "Even so, the canals' share of traffic shrank steadily, and by the end of the nineteenth century many had become quiet, half-forgotten channels.",
    "Their story is a reminder that an infrastructure can be both a triumph and, within a single lifetime, a relic."],
   "Faced with this competition, many canal companies cut their tolls sharply, and some were bought outright by the very railway companies that threatened them.",
   [1, 3, 4, 6],
   "'this competition' refers to the arrival of the railways, and the canal companies' efforts to respond are what 'Even so' in the following sentence concedes before reporting the decline. The sentence must sit between the arrival of the railways and the decline: gap (3).",
   {1: "At gap (1) only the advantages of canals have been described; there is no competition for 'this competition' to refer to.",
    3: "At gap (2) the canals are still prospering and the railways have not yet arrived, so neither the competition nor the railway companies can be mentioned.",
    6: "At gap (4) the paragraph has already drawn its lesson about triumph and relic; a detail about tolls after that conclusion is out of chronological and logical order."},
   "Choosing gap (4) by reading the sentence as a final detail of the decline, without noticing that 'Even so' needs the companies' response before it.",
   "V04F-canal-age-decline", "Chronology and a clear backward reference make the position easy to locate.",
   cognitive="Understanding")

# 010 ------------------------------------------------------------------ coinage
sp("V04-F-010", "History and politics", "Stamped coins replaced the weighing of metal with a promise, and the history of coinage is a history of that trust being broken and repaired.", "Medium",
   ["Before coins existed, traders who used metal as money had to weigh and test it at every exchange.",
    "A coin stamped by a recognised authority removed much of that labour, because the stamp was a promise that the metal was of a certain weight and purity.",
    "The promise, however, was only as good as the authority behind it.",
    "Users soon learned that edges could be clipped and metal debased, so that a coin's face and its substance could quietly part company.",
    "Milled edges and intricate designs were partly answers to this problem, making tampering easy to spot at a glance.",
    "The history of coinage is in this sense a history of trust, repeatedly lost and repaired."],
   "Such checking was slow, and it left each party at the mercy of the other's scales and honesty.",
   [1, 3, 5, 6],
   "'Such checking' refers to weighing and testing metal 'at every exchange', and the drawbacks it names, slowness and dependence on the other party, are exactly what the stamped coin 'removed'. The sentence therefore lies between the first two sentences, at gap (1).",
   {3: "At gap (2) the paragraph has moved on to the weakness of the authority's promise; no checking has been mentioned since the first sentence, and a complaint about slow weighing would interrupt the turn introduced by 'however'.",
    5: "At gap (3) 'Such checking' might seem to refer to detecting tampering, but the sentence just before it presents milled edges as making tampering 'easy to spot at a glance', so calling the checking slow would contradict it; the complaint belongs to the world before coins.",
    6: "At gap (4) the paragraph has concluded with its claim about trust; returning to the inconvenience of weighing metal after the conclusion is out of order."},
   "Choosing gap (3) because 'checking' seems to pick up the idea of detecting clipped coins, missing that the paragraph says such detection became quick.",
   "V04F-coinage-standardisation", "'Such checking' could be attached to the later talk of tampering; the solver must see which kind of checking was slow.")

# 011 ------------------------------------------------------------------ uniform postage
sp("V04-F-011", "History and politics", "Flat prepaid postage succeeded because the real cost of the post lay in handling, not distance, showing that a price can hide a cost it creates.", "Difficult",
   ["For much of its history, a letter's postage was charged according to the distance it travelled and the number of sheets it contained, and it was often paid by the recipient rather than the sender.",
    "The arrangement seemed fair, since carrying a letter across a country plainly cost more than carrying it across a town.",
    "Reformers in the nineteenth century argued that this intuition was mistaken.",
    "Most of the expense of the post, they claimed, lay not in the journey but in the handling: calculating charges, collecting money at the door and keeping accounts of every item.",
    "One cheap charge for every letter, settled beforehand by whoever posted it, would sweep away most of that work at a stroke.",
    "Critics of the proposal predicted that the post would be ruined, since each letter would now earn so much less.",
    "The lesson reaches beyond the post: a price that tracks one visible cost may conceal a larger cost that the pricing itself creates, and may suppress demand that nobody knew existed."],
   "Once the change was made, the number of letters sent rose steeply, and most of the clerical labour of working out and collecting charges at the door disappeared.",
   [3, 4, 5, 6],
   "The missing sentence reports what happened 'Once the change was made', so it must follow both the proposal of a single low rate and the prediction made by 'Critics of the proposal', which looks forward to a reform not yet carried out. It must also precede the closing lesson, whose phrase 'suppress demand that nobody knew existed' rests on the steep rise in letters. That is gap (4).",
   {3: "At gap (1) the reformers have only disputed the old intuition; neither the handling costs nor the flat rate have been described, so there is no change whose results could be reported.",
    4: "At gap (2) the reformers have explained the handling costs but not yet proposed the single low rate; there is no 'change' yet for the sentence to refer to.",
    5: "At gap (3) the flat rate has been proposed, so an outcome might seem possible, but then the 'Critics of the proposal' would be predicting the effects of a reform the paragraph has already reported as carried out and successful, which reverses the order of prediction and outcome."},
   "Choosing gap (3) because the sentence appears to follow naturally from the proposal of a single low rate, without checking that the critics' prediction concerns the proposal and so must precede the reported result.",
   "V04F-uniform-postage-rates",
   "Two adjacent gaps both follow the proposal; only the order of prediction and outcome, and the lesson's dependence on the rise in letters, separate them.",
   exams=D2)

# 012 ------------------------------------------------------------------ blank maps
sp("V04-F-012", "History and politics", "Leaving unknown regions blank on maps was more honest than decoration, but it carried its own distortion by implying empty land.", "Medium",
   ["Early modern mapmakers often filled the unknown interiors of continents with decoration: sea monsters, elephants, ornate lettering and imagined mountain ranges.",
    "Later cartographers came to regard this habit as a kind of dishonesty.",
    "Blank space, on this view, was not an admission of failure but a precise statement of the limits of knowledge.",
    "Yet the blank had distortions of its own.",
    "A region left empty on a European map was rarely empty in fact; it was simply unknown to the people who made and bought the map.",
    "To readers far away, the white space could suggest a land without inhabitants or prior claims, simply waiting to be filled by whoever arrived first."],
   "A map, they argued, should distinguish plainly between what had been surveyed and what had merely been guessed.",
   [1, 2, 4, 6],
   "'they argued' refers to the later cartographers who saw decoration as dishonest, and their principle of separating the surveyed from the guessed is the reasoning behind the next sentence's praise of blank space 'on this view'. The sentence therefore belongs at gap (2).",
   {1: "At gap (1) the only people mentioned are the early mapmakers who filled maps with decoration; making 'they' argue for a plain distinction between the surveyed and the guessed would contradict what they actually did.",
    4: "At gap (3) the paragraph has just turned with 'Yet' to the distortions of the blank; restating the case for blank space here would reverse the direction the paragraph has taken.",
    6: "At gap (4) the paragraph ends on the distortion of white space suggesting empty land; the cartographers' principle belongs with their argument, not after its criticism."},
   "Choosing gap (1) by taking 'they' to be the early mapmakers, overlooking that their decorations are the opposite of the principle stated.",
   "V04F-blank-spaces-on-maps", "The pronoun 'they' could seem to fit two groups; the content of the argument decides which.")

# 013 ------------------------------------------------------------------ loss leaders
sp("V04-F-013", "Economics and business", "Supermarkets sell some staples below cost because the cheap items draw shoppers past profitable goods.", "Easy",
   ["Grocery chains will often price a handful of everyday staples, milk, eggs or bread, so low that the margin vanishes or turns negative.",
    "At first sight this looks like generosity towards shoppers, or else like a sign of careless management.",
    "The logic becomes clear once we notice where such items are usually placed and what a shopper must pass to reach them.",
    "They tend to sit at the back of the shop, so that a customer who comes in for one cheap carton must walk past aisle after aisle of goods sold at a comfortable margin.",
    "Few people leave with only the item they came for, and the profit on what they add to the basket more than covers the loss on what brought them in."],
   "The bargain, in other words, is less a gift to the shopper than a price the shop pays for the shopper's attention.",
   [1, 2, 3, 5],
   "'in other words' marks the missing sentence as a restatement of a point already made in full. The point that the cheap item is a way of drawing shoppers past profitable goods is complete only after the last sentence, which shows the extra purchases covering the loss. The sentence therefore closes the paragraph, at gap (4).",
   {1: "At gap (1) the low prices have only been described; nothing has yet explained them, so 'in other words' would restate an argument that has not been made.",
    2: "At gap (2) the paragraph has just raised two wrong explanations, generosity and careless management; the real logic has not yet been given, so the sentence cannot sum it up.",
    3: "At gap (3) the paragraph has promised that the logic will become clear but has not yet described where the items are placed or what customers buy on the way, so the summary comes too early."},
   "Choosing gap (2) because the sentence seems to reply directly to the idea of generosity, without noticing that 'in other words' requires the explanation to come first.",
   "V04F-loss-leader-pricing", "A summarising connective points to the end once the argument is traced.",
   cognitive="Understanding")

# 014 ------------------------------------------------------------------ franchises
sp("V04-F-014", "Economics and business", "Franchisees accept tight rules because uniformity is what they are buying, though it limits their independence.", "Medium",
   ["A franchise is an unusual bargain between independence and control.",
    "The franchisee owns the shop, hires the staff and bears the risk of failure, yet must follow a manual that dictates everything from the recipe to the colour of the walls.",
    "The answer is that the constraints are precisely what is being bought.",
    "A traveller in an unfamiliar town trusts a familiar sign because every outlet behind it behaves in the same way, and that trust is worth more than any single owner could build alone.",
    "The same uniformity, however, limits what a franchisee can do when local tastes differ from the assumptions written into the manual.",
    "An owner who knows that the neighbourhood wants a different menu may be forbidden to offer it, and the independence promised at the outset turns out to be largely financial."],
   "Why would an ambitious owner accept such tight constraints on a business that is legally theirs?",
   [2, 3, 4, 6],
   "The missing sentence is a question, and the third sentence opens with 'The answer is that', which needs a question immediately before it. The question also refers to 'such tight constraints', the manual described in the second sentence. So it sits between the description of the manual and the answer: gap (1).",
   {3: "At gap (2) the answer, that 'the constraints are precisely what is being bought', would come before the question it answers, leaving 'The answer' with nothing to respond to.",
    4: "At gap (3) the paragraph has already explained why owners accept the rules through the example of the traveller's trust; asking the question after it has been answered reverses the order.",
    6: "At gap (4) the paragraph ends on the limits of a franchisee's independence; asking why owners accept the constraints here would be a question the paragraph has already answered in its third sentence."},
   "Choosing gap (4) because a closing question seems a natural way to end a paragraph about lost independence.",
   "V04F-franchise-model", "A forward set-up: the solver must notice that 'The answer' requires the question just before it.")

# 015 ------------------------------------------------------------------ irrigation commons
sp("V04-F-015", "Economics and business", "Village irrigation systems survive through farmer-made rules, which shows the conditions under which shared resources are overused.", "Difficult",
   ["A common view holds that any resource shared by many users will be overused, because whoever draws a little extra keeps all of the gain while the harm is spread thinly across everyone else.",
    "On this reasoning, a canal that waters the fields of an entire village should run dry long before the farmer at the tail end receives a share.",
    "Yet many village irrigation systems have run for generations without either private ownership or control by a distant state.",
    "The rules are usually precise: turns at the sluice gate are fixed in advance, every household sends labour to clear the channels, and because the fields lie side by side, a farmer who takes water out of turn is likely to be seen by a neighbour.",
    "Such systems do not refute the original argument so much as specify when it applies.",
    "Overuse becomes likely when users cannot watch one another, cannot keep outsiders away or have no voice in the rules, conditions that are sometimes created, ironically, when a well-meaning authority replaces local arrangements with a uniform code."],
   "What sustains them is neither altruism nor luck but a body of rules that the farmers themselves devised and continue to adjust and enforce.",
   [1, 3, 4, 6],
   "'them' in the missing sentence needs the village irrigation systems, which first appear in the third sentence, and the sentence introduces 'a body of rules' that the fourth sentence takes up as 'The rules are usually precise'. Without the missing sentence, 'The rules' would appear with no rules mentioned. The sentence therefore goes at gap (2).",
   {1: "At gap (1) only the general argument about overuse has been stated; no irrigation systems have appeared, so 'What sustains them' has nothing to refer to.",
    4: "At gap (3) the paragraph has already described the rules in detail, so the definite 'The rules' in the previous sentence would have appeared before any rules were introduced; the sentence that introduces them cannot follow their description.",
    6: "At gap (4) the paragraph has moved from the village case to the general conditions under which overuse occurs; returning to what sustains particular systems after that generalisation breaks the paragraph's movement from case to principle."},
   "Choosing gap (3) because the sentence looks like a summary of the precise rules, overlooking that the definite 'The rules' presupposes an earlier mention.",
   "V04F-village-irrigation-commons",
   "Dense argument; gap (3) is tempting because the sentence reads like a summary of the detailed rules, and only the definite article in 'The rules' rules it out.",
   exams=D2)

# 016 ------------------------------------------------------------------ warranties
sp("V04-F-016", "Economics and business", "A long warranty signals quality because it is cheap for good producers and costly for bad ones, though the signal can mislead.", "Medium",
   ["A long warranty is usually advertised as a promise to the buyer, but it is also a message about the seller.",
    "Repairing or replacing faulty goods costs money, and a firm that offers five years of cover is betting that few of its products will fail within that time.",
    "A maker of shoddy goods could print the same promise, but honouring it would soon become ruinous.",
    "Buyers who cannot inspect the inner workings of a washing machine can therefore read something about its quality from the length of its guarantee.",
    "The signal is not infallible, however.",
    "A firm in difficulty may offer generous terms it never expects to honour, and a buyer who relies on the warranty alone may find that the promise was only as solid as the company behind it."],
   "This difference in cost is what gives the message its credibility: a long warranty is cheap for a careful producer to offer and dangerous for a careless one.",
   [1, 2, 3, 5],
   "'This difference in cost' needs two costs to compare: the modest cost to a reliable firm in the second sentence and the ruinous cost to a maker of shoddy goods in the third. Only after both can the sentence explain why the message is credible, and its conclusion is what lets buyers 'therefore' read quality from the guarantee. That is gap (3).",
   {1: "At gap (1) the paragraph has only said that a warranty is a message; no costs at all have been mentioned, so 'This difference in cost' has no referent.",
    2: "At gap (2) only the reliable firm's cost has been described; the maker of shoddy goods comes in the next sentence, so there is not yet any difference to speak of.",
    5: "At gap (4) the paragraph has just said that 'The signal is not infallible'; affirming the signal's credibility at this point would contradict the qualification that the final sentence goes on to explain."},
   "Choosing gap (2) because the sentence seems to explain the firm's bet, without noticing that a 'difference' needs the shoddy maker's cost as well.",
   "V04F-warranty-signalling", "The phrase 'This difference in cost' needs both sides of a comparison, and one tempting gap has only one.")

# 017 ------------------------------------------------------------------ mangroves
sp("V04-F-017", "Science and environment", "Mangrove roots slow coastal water, protecting shores and holding sediment, so clearing them is a false economy.", "Easy",
   ["On sheltered shores across the tropics, mangroves occupy the muddy strip between dry ground and open water, a zone that every high tide submerges.",
    "This slowing brings two benefits to the people who live behind the forest.",
    "Waves driven by a storm lose much of their force before they reach the shore, and sediment carried in by the tide settles among the roots instead of being washed away.",
    "Where mangroves are cleared for farms or fish ponds, coasts that were once sheltered often begin to erode, and the cost of building sea walls can exceed whatever the cleared land earns.",
    "A forest that looks to many developers like idle swamp is, in effect, a piece of coastal infrastructure that nobody has to pay for."],
   "Their tangled roots, which rise above the mud like stilts, slow down the water that flows in and out among them.",
   [1, 2, 3, 5],
   "The second sentence begins 'This slowing', so the sentence immediately before it must describe something being slowed. Only the missing sentence does that, and its 'Their' refers back to the mangroves of the first sentence. It therefore belongs at gap (1).",
   {2: "At gap (2) the sentence would come after 'This slowing' has already been mentioned, leaving that phrase with nothing to refer to.",
    3: "At gap (3) the two benefits, weaker waves and trapped sediment, have already been described; explaining the roots' slowing effect after its benefits reverses cause and effect.",
    5: "At gap (4) the paragraph has concluded that the forest is free infrastructure; a basic description of the roots after that conclusion is out of place."},
   "Choosing gap (3) because the sentence mentions roots, as the sentence about sediment settling 'among the roots' does.",
   "V04F-mangrove-coastal-buffer", "A direct backward reference ('This slowing') locates the sentence at once.",
   cognitive="Understanding")

# 018 ------------------------------------------------------------------ pollinators
sp("V04-F-018", "Science and environment", "Single-crop farms give pollinators a brief feast followed by famine, so flowering strips that bloom at other times help.", "Medium",
   ["Farms that grow a single crop over vast areas offer pollinating insects a strange kind of feast.",
    "For a few weeks each year, when the crop flowers, food is abundant on a scale that no wild meadow could match.",
    "Insects that need a steady supply of nectar and pollen cannot survive on such a calendar, and their local populations dwindle from one year to the next.",
    "Growers who depend on pollination may then have to rent hives of honeybees that are trucked in for the flowering and taken away again as soon as it ends.",
    "Planting strips of varied flowers along field edges can help, not by competing with the crop but by feeding pollinators during the weeks when the crop cannot."],
   "For the rest of the season, however, the same fields offer almost nothing, because the weeds and hedges that once bloomed at other times have been cleared away.",
   [1, 2, 4, 5],
   "'For the rest of the season, however' contrasts with a stated period of plenty, the 'few weeks each year' when the crop flowers. The feast followed by famine is what the next sentence calls 'such a calendar', which an insect needing a 'steady supply' cannot survive. So the sentence goes between these two: gap (2).",
   {1: "At gap (1) no flowering period has been mentioned yet, so 'the rest of the season' and the contrast marked by 'however' have nothing to set themselves against.",
    4: "At gap (3) the paragraph has already reached the consequence, growers renting hives; the cause of the decline must come before the dwindling populations, not after the growers' response to them.",
    5: "At gap (4) the paragraph has ended with a remedy that depends on the idea of weeks 'when the crop cannot' feed pollinators; that idea must be introduced before the remedy, not after it."},
   "Choosing gap (4) because the sentence about weeds and hedges seems to lead naturally into the remedy of flower strips, overlooking that the remedy already presupposes it.",
   "V04F-pollinator-monoculture", "A contrast marker needs its partner; the remedy at the end makes the final gap tempting.")

# 019 ------------------------------------------------------------------ salinity
sp("V04-F-019", "Science and environment", "Irrigation deposits salt that only drainage removes, and because drains are costly and slow to pay off, they are often skipped, ruining land.", "Difficult",
   ["Irrigation is usually counted among agriculture's great successes, and rightly so: it has turned dry plains into some of the most productive farmland on earth.",
    "Yet all irrigation water, however fresh it looks, carries a small load of dissolved salts.",
    "When the water evaporates from the fields or is drawn up by plants, the salts stay behind, accumulating year after year in the upper layers of the soil.",
    "Generous watering might seem the obvious remedy, since extra water can wash the salts downwards, beyond the reach of the roots.",
    "But where the land drains poorly, the extra water raises the water table instead, and the rising groundwater carries yet more salt towards the surface.",
    "Engineers therefore insist that irrigation be paired with drainage, with channels or buried pipes that carry the salty water away from the fields.",
    "The result, in more than one region, has been fields once famous for their harvests turning white with salt and being abandoned."],
   "Such drains are expensive, however, and because their benefits appear only slowly, they are often the first item cut from a tight budget.",
   [3, 4, 5, 6],
   "'Such drains' needs drains as physical works, and these first appear as the 'channels or buried pipes' in the sentence about engineers. The missing sentence then explains why that advice is often ignored, and 'The result' in the last sentence refers to exactly this: drains cut from budgets lead to abandoned, salted fields. The sentence must therefore come between the engineers' advice and the result, at gap (4).",
   {3: "At gap (1) the paragraph has just described salt building up in the soil; no remedy, let alone a drain, has been mentioned, so 'Such drains' has no referent.",
    4: "At gap (2) the paragraph has introduced the remedy of generous watering, not drainage; 'Such drains' would refer to something that has not yet appeared.",
    5: "At gap (3) the previous sentence speaks of land that 'drains poorly', which may look like a referent, but it describes a property of soil, not drains as structures; moreover the engineers' 'therefore' must follow that waterlogging problem directly, and a sentence about budget cuts would break the link."},
   "Choosing gap (3) because 'drains poorly' seems to supply the drains, without noticing that the engineers' 'therefore' must follow the waterlogging sentence and that the drains as works appear only in the engineers' sentence.",
   "V04F-soil-salinity-irrigation",
   "Long causal chain with a near-miss referent ('drains poorly') at gap (3); the solver must also see that 'The result' depends on the budget cut.",
   exams=D2)

# 020 ------------------------------------------------------------------ bird navigation
sp("V04-F-020", "Science and environment", "Migrating birds use several navigational cues, which protects them because any single cue can fail.", "Medium",
   ["Migratory birds cross thousands of kilometres and often return to the same nesting site year after year, a feat that long puzzled naturalists.",
    "Research over the past century has shown that they rely not on one sense but on several.",
    "Many species take bearings from the sun by day and from the patterns of the stars at night.",
    "Others appear to sense the earth's magnetic field, and some may use smells or the low sound of distant surf to recognise familiar regions.",
    "Clouds, for example, hide the stars, magnetic storms can disturb the field, and a change of wind carries scents away from their source.",
    "A bird that can switch from one cue to another is far less likely to go astray than one that trusts a single guide."],
   "Having several cues matters because each of them can fail.",
   [1, 2, 4, 6],
   "The sentence beginning 'Clouds, for example' gives examples of cues failing, so the claim that 'each of them can fail' must come immediately before it. That claim in turn needs the cues to have been listed, which is done in the two sentences about the sun, the stars, the magnetic field and smells. So the sentence belongs at gap (3).",
   {1: "At gap (1) only the puzzle of migration has been stated; no cues have been mentioned, so 'several cues' and 'each of them' have nothing to refer to.",
    2: "At gap (2) the paragraph has said that birds use several senses but has not yet named them, and the examples of failure would then be separated from the claim they illustrate by two sentences listing the cues.",
    6: "At gap (4) the paragraph has already drawn its conclusion about switching cues; the claim that cues can fail is the premise of that conclusion and must come before the examples of failure and the conclusion, not after them."},
   "Choosing gap (2) because the sentence picks up the word 'several' from the sentence before it, missing that 'for example' later needs the claim of failure immediately before it.",
   "V04F-bird-migration-navigation", "The short sentence could seem to attach to the first mention of 'several'; the example sentence later fixes it.")

# 021 ------------------------------------------------------------------ monsoon forecasts
sp("V04-F-021", "Science and environment", "A forecast of total monsoon rainfall can be right yet useless, so forecasters face a trade-off between reliable but less useful and useful but less reliable predictions.", "Difficult",
   ["A seasonal forecast that predicts the total rainfall of a monsoon can be judged correct even when it is of little use to the people who most depend on it.",
    "Suppose the forecast says that the season will bring roughly its normal amount of rain, and at the end of the season the gauges confirm exactly that.",
    "By the forecaster's measure, the prediction has succeeded.",
    "A farmer who sowed on the strength of a 'normal' forecast could lose an entire crop in such a year, even though the season adds up to exactly what was promised.",
    "This is why forecasters increasingly try to predict the onset of the rains and the length of dry spells, not merely the seasonal sum.",
    "These finer predictions are harder to make and more often wrong, which leaves forecasters with an awkward choice between being reliable about what matters less and unreliable about what matters more."],
   "Yet the same total can arrive in very different ways: as steady showers spread across four months, or as a late onset, a long dry spell and a few violent downpours at the end.",
   [3, 4, 5, 6],
   "'Yet' turns against the forecaster's claim of success, so the sentence follows 'By the forecaster's measure, the prediction has succeeded'. It also supplies the bad pattern of rain that the next sentence calls 'such a year', and it introduces the onset and the dry spells that forecasters later try to predict. The sentence belongs at gap (1).",
   {4: "At gap (2) the farmer's lost crop 'in such a year' would already have been described with no year of that kind defined; the different patterns of rain must come before the loss they explain.",
    5: "At gap (3) 'This is why' might seem to follow the farmer's loss directly, but the onset and dry spells it mentions are introduced only by the missing sentence; placing it after them leaves 'such a year' unexplained and reverses the order of reason and response.",
    6: "At gap (4) the paragraph has reached its final trade-off between reliability and usefulness; going back to describe patterns of rainfall after that conclusion undoes the paragraph's development."},
   "Choosing gap (3) because the missing sentence seems to justify the turn to predicting onsets and dry spells, without noticing that the farmer's 'such a year' already depends on it.",
   "V04F-monsoon-forecasting",
   "The decisive lock is a single referent, 'such a year', in a sentence that looks self-contained, and gap (3) appears to offer a reason for the shift in forecasting.",
   exams=D2)

# 022 ------------------------------------------------------------------ spreadsheets
sp("V04-F-022", "Technology", "The ease that makes spreadsheets popular also lets errors spread unseen, so careful checking habits matter more than better software.", "Easy",
   ["Spreadsheets are among the most widely used tools in business, and much of their appeal lies in how easily anyone can build one.",
    "That same ease, which lets a manager with no training produce a working model in an afternoon, is also their weakness.",
    "Because the formulas are hidden behind the numbers they produce, such errors can sit unnoticed for months while decisions are made on the basis of the wrong figures.",
    "Organisations sometimes discover, too late, that a forecast or a budget rested on a cell that pointed to the wrong range.",
    "The remedy is less a better program than a better habit: checking, documenting and asking a second person to read the logic behind any sheet that matters."],
   "A formula typed into a single cell can be copied across hundreds of rows in a second, and any mistake in it is copied just as faithfully.",
   [1, 2, 4, 5],
   "The missing sentence shows how the ease of building a spreadsheet becomes a weakness, so it follows 'is also their weakness'. It also introduces the 'mistake' that the next sentence calls 'such errors'. The sentence therefore belongs at gap (2).",
   {1: "At gap (1) no weakness has been mentioned, and 'That same ease' in the following sentence must come straight after the first sentence's 'how easily anyone can build one'.",
    4: "At gap (3) the errors have already been described as sitting unnoticed for months; explaining how a mistake spreads after its consequences reverses the order, and 'such errors' would have had no referent.",
    5: "At gap (4) the paragraph has ended with its remedy; describing how errors are copied after the remedy is out of sequence."},
   "Choosing gap (3) because the sentence about the wrong range also concerns a faulty cell, without noticing that 'such errors' needs an earlier mention of a mistake.",
   "V04F-spreadsheet-errors", "A plain backward reference ('such errors') fixes the gap.",
   cognitive="Understanding")

# 023 ------------------------------------------------------------------ automation
sp("V04-F-023", "Technology", "More reliable automation can leave its supervisors less ready for the rare failures that matter, so designers keep humans in practice.", "Difficult",
   ["It seems obvious that a more reliable automatic system should make the people who supervise it safer.",
    "In one sense it does: fewer failures mean fewer occasions on which a human must step in.",
    "But those occasions do not disappear, and they tend to be the hardest ones, the situations that the designers did not foresee.",
    "Meanwhile, an operator who has watched a system perform flawlessly for months has had little reason to stay alert and little chance to practise the skills that intervention requires.",
    "Some designers respond by handing control back to operators from time to time, not because the machine needs help but because the human needs practice.",
    "The aim is not to make the system less capable but to keep the person watching it capable as well."],
   "The better the automation, then, the less prepared its supervisor may be for the moment it fails.",
   [1, 2, 4, 6],
   "The missing sentence draws a conclusion ('then') from two premises: the failures that remain are the hardest, and the operator has had little chance to practise. Both are in place only after the sentence beginning 'Meanwhile'. The conclusion is the problem to which 'Some designers respond', so it must come before that sentence. That is gap (3).",
   {1: "At gap (1) the paragraph has only stated the common assumption; 'In one sense it does' must answer that assumption directly, and the conclusion has no premises yet.",
    2: "At gap (2) the paragraph has conceded that reliability helps; nothing yet shows that the remaining failures are hard or that operators lose skill, so 'then' would draw a conclusion from premises not yet stated.",
    6: "At gap (4) the paragraph has already described the designers' response and its aim; restating the problem after the remedy reverses the order of problem and response and leaves 'respond' without the conclusion it answers."},
   "Choosing gap (4) because the sentence reads like a neat closing paradox, overlooking that the designers' response presupposes it.",
   "V04F-automation-complacency",
   "The sentence has no pronoun to anchor it; the solver must trace which premises it needs and see that the closing gap, though tempting as a summary, follows the remedy.",
   exams=D2)

# 024 ------------------------------------------------------------------ undo
sp("V04-F-024", "Technology", "The undo command made mistakes cheap and so encouraged an experimental style of working.", "Easy",
   ["Few computer users today give a thought to the undo command, yet it altered the experience of working at a screen in ways that deserve more notice.",
    "Before it became common, a single wrong keystroke could destroy an hour of work, and cautious users learned to save copies of everything.",
    "With a reliable way back, people began to treat the screen as a place for trying things out.",
    "Experiment of this kind, once risky, became cheap, and work that would once have been planned carefully on paper could now be discovered by trial and error.",
    "In this way a small technical feature, rarely noticed by the people who rely on it, quietly encouraged a bolder and more exploratory style of thinking."],
   "A writer could delete a whole paragraph to see whether an argument read better without it, knowing that a single command would bring it back.",
   [0, 1, 2, 3],
   "The missing sentence is an example of 'trying things out', made possible by a 'reliable way back', and it is the 'Experiment of this kind' that the next sentence refers to. It therefore comes between those two sentences, at gap (4).",
   {0: "Gap (1) is before the opening sentence; an example of deleting a paragraph cannot open the paragraph before the undo command has even been introduced.",
    1: "At gap (2) the paragraph has only introduced the undo command; the example would come before the account of what working was like without it.",
    2: "At gap (3) the paragraph is describing the time before undo became common, when 'a single wrong keystroke could destroy an hour of work'; confidence that 'a single command would bring it back' contradicts that description."},
   "Choosing gap (3) because the sentence about lost work also concerns editing, without noticing that it describes the time before undo.",
   "V04F-undo-command-software", "An example after a claim, with a clear backward reference in the next sentence.",
   cognitive="Understanding")

# 025 ------------------------------------------------------------------ road signs
sp("V04-F-025", "Technology", "Road sign lettering is designed for legibility under poor conditions, in ways drivers do not notice.", "Medium",
   ["Road signs are read under conditions that would defeat most printed text: at speed, from a distance, often at night and in rain.",
    "Their lettering is therefore designed for legibility rather than elegance.",
    "The gaps between neighbouring letters are made wider than in a printed book, for a similar reason.",
    "Designers also tend to favour a mix of capital and small letters over capitals alone, since the varied outline of a word in mixed case is thought to help a driver recognise it as a shape before reading every letter.",
    "None of these choices is apparent to most drivers, which is as it should be: a sign succeeds when it is read without being noticed."],
   "Individual letters are drawn with generous open spaces inside them, so that an 'e' does not close up into an 'o' when headlights make the strokes glow and spread.",
   [2, 3, 4, 5],
   "The sentence about spacing between letters says it is wider 'for a similar reason', so it must follow a sentence that gives a reason of the same kind. The missing sentence does exactly that: open spaces inside letters stop them blurring together when the strokes 'glow and spread'. It is also the first concrete instance of designing 'for legibility'. The sentence belongs at gap (1).",
   {3: "At gap (2) the sentence about spacing would already have said 'for a similar reason' with no reason before it, since the general claim about legibility gives no specific reason.",
    4: "At gap (3) the paragraph has moved to the choice of mixed case and word shapes; a sentence about the insides of letters would interrupt that point and leave 'for a similar reason' unexplained.",
    5: "At gap (4) the paragraph has concluded that the choices go unnoticed; adding a new design choice after 'None of these choices' has summed them up is out of place."},
   "Choosing gap (2) because the open spaces inside letters seem to belong with the spacing between letters, without noticing that the spacing sentence depends on a reason given before it.",
   "V04F-road-sign-lettering", "A phrase of comparison ('for a similar reason') needs a specific reason immediately before it.")
